import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_decl = r"""
#include <torch/extension.h>
torch::Tensor max_reduce_forward(torch::Tensor x, int64_t dim);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

#include <cfloat>
template <typename T>
__global__ void max_reduce_kernel(
    const T* __restrict__ X,
    T* __restrict__ Y,
    long outer_size, long reduce_size, long inner_size)
{
    // Two-dimensional block: threadIdx.x indexes the inner (contiguous) dimension,
    // threadIdx.y splits the reduction dimension across multiple threads to
    // increase memory-level parallelism (more concurrent in-flight loads) for
    // the large reduce_size, then a fast shared-memory tree reduction combines
    // the partial maxima before writing the final result.
    extern __shared__ unsigned char smem_raw[];
    T* sdata = reinterpret_cast<T*>(smem_raw);
    const int tx = threadIdx.x;
    const int ty = threadIdx.y;
    const long inner_idx = (long)blockIdx.x * (long)blockDim.x + (long)tx;
    const bool valid = inner_idx < inner_size;
    for (long outer_idx = blockIdx.y; outer_idx < outer_size; outer_idx += (long)gridDim.y) {
        T maxval = (T)(-FLT_MAX);
        if (valid) {
            const T* __restrict__ base_ptr = X + outer_idx * reduce_size * inner_size + inner_idx;
            const T* __restrict__ ptr = base_ptr + (long)ty * inner_size;
            const long stride = (long)blockDim.y * inner_size;
            if (ty < reduce_size) {
                maxval = __ldg(ptr);
                ptr += stride;
                #pragma unroll 4
                for (long r = (long)ty + blockDim.y; r < reduce_size; r += blockDim.y) {
                    T v = __ldg(ptr);
                    maxval = v > maxval ? v : maxval;
                    ptr += stride;
                }
            }
        }
        sdata[ty * blockDim.x + tx] = maxval;
        __syncthreads();
        for (unsigned int offset = blockDim.y >> 1; offset > 0; offset >>= 1) {
            if ((unsigned int)ty < offset) {
                T other = sdata[(ty + offset) * blockDim.x + tx];
                T cur = sdata[ty * blockDim.x + tx];
                sdata[ty * blockDim.x + tx] = other > cur ? other : cur;
            }
            __syncthreads();
        }
        if (ty == 0 && valid) {
            Y[outer_idx * inner_size + inner_idx] = sdata[tx];
        }
        __syncthreads();
    }
}
torch::Tensor max_reduce_forward(torch::Tensor x, int64_t dim) {
    TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
    TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
    auto x_c = x.contiguous();
    int64_t ndim = x_c.dim();
    if (dim < 0) dim += ndim;
    TORCH_CHECK(dim >= 0 && dim < ndim, "dim out of range");
    auto sizes = x_c.sizes();
    long outer_size = 1;
    for (int64_t i = 0; i < dim; ++i) outer_size *= sizes[i];
    long reduce_size = sizes[dim];
    long inner_size = 1;
    for (int64_t i = dim + 1; i < ndim; ++i) inner_size *= sizes[i];
    std::vector<int64_t> out_sizes;
    for (int64_t i = 0; i < ndim; ++i) {
        if (i != dim) out_sizes.push_back(sizes[i]);
    }
    auto y = torch::empty(out_sizes, x_c.options());
    const int threads_x = 32;
    const int threads_y = 8;
    dim3 block(threads_x, threads_y);
    long grid_x = (inner_size + threads_x - 1) / threads_x;
    long grid_y = outer_size < 65535 ? outer_size : 65535;
    if (grid_y < 1) grid_y = 1;
    dim3 grid((unsigned int)grid_x, (unsigned int)grid_y);
    size_t smem_bytes = (size_t)threads_x * (size_t)threads_y * sizeof(float);
    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
    max_reduce_kernel<float><<<grid, block, smem_bytes, stream>>>(
        x_c.data_ptr<float>(),
        y.data_ptr<float>(),
        outer_size, reduce_size, inner_size
    );
    auto err = cudaGetLastError();
    TORCH_CHECK(err == cudaSuccess, "max_reduce_kernel launch failed: ", cudaGetErrorString(err));
    return y;
}
"""

max_reduce_ext = load_inline(
    name="cute_max_reduce_ext",
    cpp_sources=cuda_decl,
    cuda_sources=cuda_src,
    functions=["max_reduce_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=[
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include",
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include/cute/",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Simple model that performs Max reduction over a specific dimension,
    implemented with a custom CUDA kernel using CuTe tensors.
    """
    def __init__(self, dim: int):
        super(ModelNew, self).__init__()
        self.dim = dim
        self._ext = max_reduce_ext

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self._ext.max_reduce_forward(x, self.dim)

