        #pragma unroll 8
        for (long r = 1; r < reduce_size; ++r) {
            T v = __ldg(ptr);
            maxval = v > maxval ? v : maxval;
            ptr += inner_size;
        }
        Y[outer_idx * inner_size + inner_idx] = maxval;
    }
}

